// ---- Translations: generated by build/build.py from lang/*.json, do not edit ----
const I18N_TEXTS = {
  "en": {"install.done": "{count} macros installed/updated.", "install.refresh": "Refresh the Foundry window (F5) to apply the updated session start script.", "macro.custom_roll": "Custom roll", "macro.private_message": "Private message", "macro.trait_roll": "Roll 1d{die} + Wild Die"},
  "fr": {"install.done": "{count} macros installées/mises à jour.", "install.refresh": "Rafraîchis la fenêtre de Foundry (F5) pour appliquer le script de démarrage de session mis à jour.", "macro.custom_roll": "Lancer personnalisé", "macro.private_message": "Message privé", "macro.trait_roll": "Lancer 1d{die}+Joker"}
};
const t = (key, vars = {}) => {
  const lang = String(game.i18n?.lang ?? "en");
  for (const code of [lang, lang.split("-")[0], "en"]) {
    const table = I18N_TEXTS[code];
    if (!table) continue;
    let text = table[key];
    if (text === undefined && vars.n !== undefined) {
      text = table[`${key}.${new Intl.PluralRules(code).select(vars.n)}`] ?? table[`${key}.other`];
    }
    if (text !== undefined) return text.replace(/\{(\w+)\}/g, (match, name) => name in vars ? String(vars[name]) : match);
  }
  return key;
};
// ---- End of translations ----

// Deterministic (non-random) hash of a string, used to derive a stable, unique
// file name from the SVG's content.
function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (Math.imul(hash, 31) + str.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16);
}

